script:
loadScript("https://cdn.jsdelivr.net/npm/frappe-gantt/dist/frappe-gantt.umd.js");
loadCss("https://cdn.jsdelivr.net/npm/frappe-gantt/dist/frappe-gantt.css");

function loadScript(url) {
    const script = document.createElement('script');
    script.src = url;
    document.body.appendChild(script);
}

function loadCss(filename) {
    var link = document.createElement('link');
    link.rel = 'stylesheet';
    link.type = 'text/css';
    link.href = filename;
    document.head.appendChild(link);
}

function _build_gantt( nodes, holidays = null ) {
    $('#task-gantt').empty();
    return new Gantt('#task-gantt', 
        get_tasks( nodes ),
        {
            lines: "both ",             // none for no lines, vertical for only vertical lines, horizontal for only horizontal lines, both for complete grid.
            today_button: true,
            scroll_to: 'today',         // или 'start', 'end', или конкретная дата  
            view_mode: "Day",            // Day, Week, Month, Year
            view_mode_select: true,
            view_modes: [  
                Gantt.VIEW_MODE.DAY, 
                Gantt.VIEW_MODE.WEEK,
                //Gantt.VIEW_MODE.MONTH
            ],
            infinite_padding: false ,   // Фиксированный интервал  
            arrow_curve: 3,             // Curve radius of arrows connecting dependencies.
            //auto_move_label: true,      // Move task labels when user scrolls horizontally.
            move_dependencies: false,    // Whether moving a task automatically moves its dependencies.
            //show_expected_progress: true,
            //snap_at: "1d",            // Snap tasks at particular intervel while resizing or dragging.
            popup_on: "click",
            popup: _show_popup,
            on_date_change: _on_date_change,    
            //on_click: ( task )                    // клик по задаче
            on_double_click: _on_dbl_click,
            on_hover: _on_hover,
            //on_progress_change: (task, progress)  // изменение прогресса задачи
            //on_view_change:                       // изменение режима просмотра
            language: frappe.boot.lang,
            upper_header_height: 40,    //45
            lower_header_height: 26,    //30
            bar_corner_radius: 1,
            padding: 8,
            bar_height: 19,
            //container_height: 400,
            column_width: 25,
            holidays: {
                'var(--g-weekend-highlight-color)': holidays.filter( (d) => ( d.weekly_off ) ),
                'var(--g-holiday-highlight-color)': holidays.filter( (d) => ( !d.weekly_off ) ),
            },             
            readonly: !frappe.model.can_write("Task"),
            readonly_progress: true,
            readonly_dates: false,
    });
}

function _sync_scroll() {
    //Сиинхронизация вертикальных скроллбаров
    $(".tree-table").scroll(function() {
        $(".gantt-container").scrollTop($(".tree-table").scrollTop());
    });
    $(".gantt-container").scroll(function() {
        $(".tree-table").scrollTop($(".gantt-container").scrollTop());
    });
}

let _c;

function _on_hover( task, x, y, event ) {
    clearTimeout(_c);
    $(".tree-table .tree-link, .tree-table .tree-row").removeClass("hover");

    let node = cur_tree.nodes[ task.id ];
    
    if ( node ) {
        node.$tree_link.addClass("hover");
        node.$row.addClass("hover");
        _c = setTimeout( () => {
            node.$tree_link.removeClass("hover");
            node.$row.removeClass("hover");
        }, 500 );
    }
}

function _on_dbl_click( task ) {
    frappe.set_route("Form", "Task", task.id );
}

let _save_data = {};
let _timerId = {};

async function _on_date_change(task, start, end) {
    console.log( task + ": " + start + "-" + end );
    _save_data[ task.id ] = {
        task: task,
        start: start,
        end: end,
    };
    
    if ( _timerId[ task.id ] ) {
        clearTimeout( _timerId[ task.id ] );
    }
    
    _timerId[ task.id ] = setTimeout(async () => {
        await _save_node( task.id );
        _save_data[ task.id ] = {};
    }, 1000);
}

async function _save_node( task_id ) {
    let task = _save_data[ task_id ].task;
    let start = _save_data[ task_id ].start;
    let end = _save_data[ task_id ].end;
    
    let has_changes= false;
    let save_fields = [];
    let save_values = [];
    let old_values = [];

    if ( frappe.datetime.get_day_diff( task.start, start ) ) {
        old_values.push( task.node.exp_start_date );
        task.start = frappe.datetime.obj_to_str( start );
        setNodeValue( task.id, "exp_start_date", task.start );
        save_fields.push( "exp_start_date" );
        save_values.push( task.start );
        has_changes = true;
    }
    if ( frappe.datetime.get_day_diff( task.end, end ) ) {
        old_values.push( task.node.exp_end_date );
        task.end = frappe.datetime.obj_to_str( end );
        setNodeValue( task.id, "exp_end_date", task.end );
        save_fields.push( "exp_end_date" );
        save_values.push( task.end );
        has_changes = true;
    }
    if ( has_changes ) {
        await saveNodeData( task_id, save_fields, save_values, old_values );
    }
}

function _show_popup(ctx) {
    ctx.set_title(ctx.task.name);
    
    const start_date = moment( ctx.task.start ).format( 'MMM D' );
    const end_date = moment( ctx.task.end ).format( 'MMM D' );

    ctx.set_subtitle(
        `${start_date} - ${end_date} (${__("Days")}: ${ctx.task.actual_duration + 
            ( ctx.task.ignored_duration ? ' + ' + ctx.task.ignored_duration + ' ' + __('excluded') : '') 
        })<br/>${__("Progress")}: ${Math.floor(ctx.task.progress * 100) / 100}%`,
    );
    
    if ( ctx.task.node.assign ) {
        ctx.set_details( `<div class="gantt-assign-avatars">
            ${ frappe.avatar_group( JSON.parse( ctx.task.node.assign ), 5, { filterable: false } )[0].outerHTML }
            </div>`);
    } else {
        ctx.set_details(`<div class="gantt-assign-avatars">${frappe.utils.icon("assign", "md" )}</div>`);
    }
    
    createAssignmentDialog( $( ".gantt-assign-avatars" ), ctx.task.node );
}

function highlight_node_gantt( tree, node, on = true ) {
    console.log("***** Gantt: highlight_node_gantt: " + on + " ****** " );
    let bar = tree.gantt.get_bar( node.data.value );
    
    if ( on ) {
        $(bar.$bar).addClass("highlight");
    } else {
        $(bar.$bar).removeClass("highlight");
    }
}

function update_node_gantt( tree, node, ignpre_dependents = false ) {
    console.log("***** Gantt: update_node_gantt ****** " );
    let bar = tree.gantt.get_bar( node.value );
    let task = tree.gantt.get_task( node.value );
    bar.group.classList.remove( task.custom_class );  
    tree.gantt.update_task( node.value, _get_task( node ) );
    tree.gantt.hide_popup();
    bar.update_arrow_position();
    
    if ( !ignpre_dependents ) {
        let dependents = tree.gantt.get_all_dependent_tasks( node.value );
        dependents.forEach( dependent => {
            let dependent_task = tree.gantt.get_task( dependent );
            update_node_gantt( tree, dependent_task.node, true );
        });
    }/**/
}


function click_node_gantt( tree, node, hide ) {
    console.log("***** Gantt: click_node_gantt ****** " );
    if ( tree.gantt ) {
        node._expanded = !hide;
        _toggle_children( tree.gantt.nodes, node.value, hide );
        tree.gantt.refresh( get_tasks( tree.gantt.nodes ) );
        tree.gantt.set_scroll_position( node.exp_start_date );
        _bind_holiday_labels();
    }
}

function _bind_holiday_labels( ) {
    $(".holiday-highlight").each(function(index, e) {
        const i = $(".label_" + e.classList[1]);
        if (!i)
            return;
        let s;
        this.onmouseenter = r => {
            s = setTimeout( () => {
                i.addClass("show"),
                i.css( "left", ( r.clientX  ) + "px"),
                i.css( "top", (r.clientY ) + "px")
            }
            , 300)
        }
        ,
        this.onmouseleave = r => {
            clearTimeout(s),
            i.removeClass("show")
        }
    } );
}

function _toggle_children( nodes, parent, hide ) {
    for ( node of nodes ) {
        if ( node.parent_task == parent ) {
            node._hide = hide;
            
            if ( node._expanded ) {
                _toggle_children( nodes, node.value, hide );
            }
        }
    }
}

async function add_nodes_to_gantt( tree, new_nodes ) {
    console.log("***** Gantt: add_nodes_to_gantt ****** " );
    let nodes = add_child_nodes( tree.gantt?.nodes, new_nodes );
    
    if ( !tree.gantt ) {
        let holidays = await _get_holidays( tree.root_value );
        tree.gantt = _build_gantt( nodes, holidays );
        _bind_holiday_labels();
        _sync_scroll();
    } else {
        //tree.gantt.refresh( get_tasks( nodes ) );
    }
    
    tree.gantt.nodes = nodes;
    return tree.gantt;
}

async function _get_holidays( project ) {
    let holidays_data = [];
    let r = await frappe.db.get_value('Project', project, ['holiday_list', 'company']);
    
    if ( r && r.message ) {
        let values = r.message;
        let holidays = values.holiday_list;
        
        if ( !holidays && values.company ) {
            let c_r = await frappe.db.get_value('Company', values.company, ['default_holiday_list']);
            holidays = c_r?.message?.default_holiday_list;
        }
        
        if ( holidays ) {
            let hd_r = await frappe.db.get_doc('Holiday List', holidays );
            holidays_data = hd_r?.holidays?.map( (d) => ( { 
                name: __(frappe.utils.html2text( d.description )), 
                date: d.holiday_date, 
                weekly_off: d.weekly_off } ) );
        }
    }
    return holidays_data;
}

function add_child_nodes( current, nodes ) {
    let tree_nodes = [];
    let skip_childs = [];
    let has_root = nodes.some( (node) => ( node.parent_task == null ) )
    
    if ( !current || has_root ) {
        tree_nodes = nodes;
    } else {
        for ( cur_node of current ) {
            if ( skip_childs.includes( cur_node.parent_task ) ) {
                skip_childs.push( cur_node.value );
            } else {
                tree_nodes.push( cur_node );
            
                if ( nodes.some( (node) => ( node.parent_task == cur_node.value ) ) ) {
                    tree_nodes = tree_nodes.concat( nodes );
                    skip_childs.push( cur_node.value );
                }
            }
        }
    } 
    
    return tree_nodes;
}

function get_tasks( nodes ) {
    let tasks = [];
    
    if ( nodes) {
        tasks = nodes.filter( (node) => !node._hide )
            .map((node) => ( _get_task( node ) ));
    }
    
    return tasks;
}

function _get_task( node ) {
    return {
                id: node.value,  
                name: node.subject,  
                start: node.exp_start_date ? ( node.exp_start_date + " 00:00:00" ) : node.creation,
                end: node.exp_end_date ? node.exp_end_date  + ( node.is_milestone ? " 00:00:00" : " 23:59:59" ) : ( node.exp_start_date ? ( node.exp_start_date + " 00:00:00" ) : node.creation ),
                progress: node.progress,                                            // Progress percentage (0-100)
                dependencies: node.relations.map(r=>r.predecessor),//.join(","),       // Comma-separated task IDs that this task depends on (e.g., '1,2,3')
                //duration: '4d',
                thumbnail: ( node.is_milestone ) ? "/files/rhombus.png" : null,
                custom_class: node.priority || "",
                node: node,
                color: _get_task_color( node ),
                color_progress: 'var(--bg-green)',
            };
}

function _get_task_color( node ) {
    switch( node.status ) {
        case 'Open': 
            return null;
        case 'Working': 
            return null;//"var(--bg-blue)";
        case 'Pending Review': 
            return "var(--bg-dark-blue)";
        case 'Overdue': 
            return "var(--alert-bg-danger)";
        case 'Template': 
            return null;
        case 'Completed': 
            return "var(--bg-green)";
        case 'Cancelled': 
            return "var(--bg-light-gray)";               
        default:
            return null;
    }
}

