        --g-row-border-color: #898989;
        --g-header-background: #191919;
        --g-actions-background: #272727;
        --g-light-border-color: #3e3e3e;
        --g-text-muted: #eee;
        --g-text-dark: #ececec;
        --g-text-color: #f7f7f7;
        --g-progress-color: #173b2c;
        --g-weekend-highlight-color: 5e5e5e;
        --g-holiday-highlight-color: #082a08;
